**FastMCP — high-level, single- and multi-turn prompts:**
```python
from mcp.server.fastmcp import FastMCP
from mcp.server.fastmcp.prompts import base

mcp = FastMCP("review-server")

@mcp.prompt()
def code_review(code: str, language: str = "python") -> str:
    """Ask the model to review a snippet for bugs and style."""
    return f"Review this {language} code:\n\n```{language}\n{code}\n```"

@mcp.prompt()
def debug_error(error: str) -> list[base.Message]:
    """Seed a multi-turn debugging conversation."""
    return [
        base.UserMessage(f"I'm seeing this error:\n{error}"),
        base.AssistantMessage("Got it — what did you last change before this started?"),
    ]
```
FastMCP infers `name` from the function, `description` from the docstring, and `arguments` from the signature — `language` becomes optional because it has a default.

**Low-level server + the wire trace it produces:**
```python
from mcp.server import Server
from mcp.types import GetPromptResult, Prompt, PromptArgument, PromptMessage, TextContent

server = Server("review-server")

@server.list_prompts()
async def list_prompts() -> list[Prompt]:
    return [Prompt(
        name="code_review",
        description="Review code for bugs and style",
        arguments=[PromptArgument(name="code", required=True)],
    )]

@server.get_prompt()
async def get_prompt(name: str, arguments: dict[str, str] | None) -> GetPromptResult:
    if name != "code_review":
        raise ValueError(f"unknown prompt: {name}")
    text = f"Review this code:\n\n{arguments['code']}"
    return GetPromptResult(
        messages=[PromptMessage(role="user", content=TextContent(type="text", text=text))]
    )
```
